'use strict';
const $=id=>document.getElementById(id);
let current=null,source=null,latestEvents=[],replay=null,replayIndex=0,replayTimer=null,clockOffset=0;
const matchId=()=>new URL(location.href).searchParams.get('match');
const coordinate=p=>String.fromCharCode(65+p.x)+(p.y+1);
function notice(message,error=false){$('notice').textContent=message;$('notice').className=error?'notice error':'notice';}
async function api(path,options={}){const r=await fetch(path,options);const date=r.headers.get('date');if(date)clockOffset=Date.parse(date)-Date.now();const data=await r.json();if(!r.ok)throw new Error(data.error?.message||'Server request failed.');return data;}
function publicLink(id){const url=new URL(location.href);url.search='';url.hash='';url.searchParams.set('match',id);return url.href;}
function setMatch(id){const url=new URL(location.href);url.searchParams.set('match',id);url.hash='';history.replaceState(null,'',url);$('matchId').value=id;$('shareLink').value=publicLink(id);$('matchCode').textContent=' / '+id.slice(0,8).toUpperCase();}
function joinPrompt(id,seat){return `Use the Agent Arena MCP tools to play match ${id}.\nPrivate seat token: ${seat.seat_token}\n\nCall get_rules, then join_match with this match_id and seat_token. Choose a unique stable agent_id and a short public name. Keep that agent_id for reconnects. Read the observation. When your_turn is true, select one action from legal_actions and call submit_action with expected_turn and a unique request_id. When waiting, call wait_for_turn rather than rapidly polling. Continue until the match finishes, subject to your tool permissions and usage limits. Keep the seat token private. If you stop, I may ask you to continue. Do not call any model API on my behalf.\n\nArena connection: ${location.origin}/mcp\nSpectator link: ${publicLink(id)}`;}
function showInvites(id,seats){$('invites').hidden=false;seats.forEach((seat,i)=>{$('prompt'+i).value=joinPrompt(id,seat);});}
function savedInvites(id){try{const seats=JSON.parse(sessionStorage.getItem('arena:'+id)||'null');if(seats)showInvites(id,seats);else $('invites').hidden=true;}catch{$('invites').hidden=true;}}
async function createMatch(){const btn=$('createMatch');btn.disabled=true;try{const hostKey=$('hostKey').value;const data=await api('/api/matches',{method:'POST',headers:{'Content-Type':'application/json',...(hostKey?{Authorization:'Bearer '+hostKey}:{})},body:'{}'});try{sessionStorage.setItem('arena:'+data.match.id,JSON.stringify(data.seats));}catch{}setMatch(data.match.id);showInvites(data.match.id,data.seats);connect(data.match.id);notice('Arena created. Send each private invitation to a different assistant.');}catch(e){notice(e.message,true);}finally{btn.disabled=false;}}
function render(state,events=latestEvents){current=state;const board=$('board');board.textContent='';for(let y=0;y<7;y++)for(let x=0;x<7;x++){const p={x,y},tile=document.createElement('div');const wall=state.walls.some(w=>w.x===x&&w.y===y);const danger=Math.min(x,y,6-x,6-y)<state.dangerRing;tile.className='tile'+(wall?' wall':'')+(danger?' danger':'');tile.dataset.pos=`${x},${y}`;tile.title=coordinate(p)+(wall?' · Cover':danger?' · Danger':'');const index=state.agents.findIndex(a=>a.x===x&&a.y===y);if(index>=0){const unit=document.createElement('span');unit.className='unit'+(index===1?' enemy':'');unit.textContent=index===0?'◈':'⟁';unit.setAttribute('aria-label',state.agents[index].name);tile.append(unit);}else if(state.pickups.some(a=>a.x===x&&a.y===y)){const pickup=document.createElement('span');pickup.className='pickup';pickup.textContent='✦';tile.append(pickup);}const coord=document.createElement('small');coord.className='tile-coordinate';coord.textContent=coordinate(p);tile.append(coord);board.append(tile);}
  state.agents.forEach((a,i)=>{$('name'+i).textContent=a.name;$('hp'+i).textContent=a.hp+' / 100';$('bar'+i).style.width=a.hp+'%';$('energy'+i).textContent=a.energy+' / 6';$('damage'+i).textContent=a.damage;$('thought'+i).textContent=a.lastAction;$('seatStatus'+i).textContent=a.joined?'● REGISTERED':'○ WAITING';$('agentState'+i).textContent=!a.joined?'AWAITING CONNECTION':state.phase==='finished'?'MATCH FINISHED':state.activeSeat===i?'CHOOSING AN ACTION':'WAITING FOR OPPONENT';document.querySelectorAll('.agent')[i].classList.toggle('active-agent',state.phase==='active'&&state.activeSeat===i);});
  $('round').textContent='TURN '+String(state.turn).padStart(2,'0')+' / 60';$('zone').textContent=state.dangerRing?'DANGER · RING '+state.dangerRing:'ZONE STABLE';$('status').textContent=replay?'MATCH REPLAY':state.phase==='waiting'?'WAITING FOR AGENTS':state.phase==='active'?'MATCH IN PROGRESS':'MATCH COMPLETE';$('overlay').hidden=state.phase==='active';$('overlay').style.display=state.phase==='active'?'none':'flex';
  if(state.phase==='waiting'){$('overlayTitle').textContent='Bring your agents.';$('overlayText').textContent=state.agents.filter(a=>a.joined).length+' of 2 connected. Send the private seat prompts to your assistants.';$('overlayTag').textContent='THE FOUNDRY / READY';}
  if(state.phase==='finished'){$('overlayTitle').textContent=state.winner===null?'A perfect stalemate.':state.agents[state.winner].name+' wins.';$('overlayText').textContent='Rule-based result · '+state.reason.replaceAll('_',' ')+' · '+state.turn+' turns';$('overlayTag').textContent='MATCH COMPLETE';}
  $('downloadReplay').disabled=false;$('watchReplay').disabled=false;$('eventCount').textContent=String(events.length).padStart(2,'0')+' EVENTS';const log=$('log');log.textContent='';if(!events.length)log.textContent='Waiting for the first connection.';for(const event of events){const row=document.createElement('div');row.className='event';const time=document.createElement('time');time.textContent='T '+String(event.turn).padStart(2,'0');const name=document.createElement('b');name.textContent=event.seat===null?'ARENA':state.agents[event.seat].name;if(event.seat===1)name.className='enemy';const message=document.createElement('span');message.textContent=event.message;row.append(time,name,message);log.append(row);}updateClock();
}
function updateClock(){if(!current||replay){$('turnClock').textContent=replay?'RECORDED ACTIONS':'NO ACTIVE MATCH';return;}if(current.phase==='active')$('turnClock').textContent=current.agents[current.activeSeat].name+' TO ACT · '+Math.max(0,Math.ceil((current.deadline-Date.now()-clockOffset)/1000))+'s';else $('turnClock').textContent=current.phase==='finished'?'REFEREE: RESULT FINAL':'TWO EXTERNAL AGENTS REQUIRED';}
function accept(data){if(replay)return;if(current?.id===data.match.id&&current.version>data.match.version)return;const previous=current;latestEvents=data.events;render(data.match,data.events);if(previous&&previous.id===data.match.id&&data.match.turn>previous.turn){const event=data.events[0];if(event?.action?.type==='attack'){const target=data.match.agents[1-event.seat];[...$('board').children].find(t=>t.dataset.pos===`${target.x},${target.y}`)?.classList.add('hit');}}}
function stopReplay(){clearInterval(replayTimer);replayTimer=null;replay=null;$('replayControls').hidden=true;$('watchReplay').textContent='↺ Watch replay';}
async function connect(id){source?.close();stopReplay();current=null;setMatch(id);try{const data=await api('/api/matches/'+encodeURIComponent(id));accept(data);source=new EventSource('/api/matches/'+encodeURIComponent(id)+'/events');source.addEventListener('state',event=>{accept(JSON.parse(event.data));$('connection').textContent='● LIVE CONNECTION';});source.onerror=()=>{$('connection').textContent='○ RECONNECTING';};source.onopen=()=>{$('connection').textContent='● LIVE CONNECTION';};}catch(e){notice(e.message,true);}}
async function watchReplay(){if(!current)return;if(replay){stopReplay();connect(matchId());return;}try{const data=await api('/api/matches/'+current.id+'/replay');replay=data;replayIndex=0;$('replayControls').hidden=false;$('watchReplay').textContent='● Return to live';$('replaySeek').max=Math.max(0,data.frames.length-1);showFrame(0);}catch(e){notice(e.message,true);}}
function showFrame(index){if(!replay)return;replayIndex=index;const frame=replay.frames[index];if(!frame)return;render(frame.state,replay.frames.slice(0,index+1).map(f=>f.event).reverse());$('replaySeek').value=index;$('replayPosition').textContent=(index+1)+' / '+replay.frames.length;}
async function downloadReplay(){if(!current)return;try{const data=await api('/api/matches/'+current.id+'/replay');const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='arena-'+current.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){notice(e.message,true);}}
async function copy(id,button){try{await navigator.clipboard.writeText($(id).value);const original=button.textContent;button.textContent='Copied ✓';setTimeout(()=>button.textContent=original,1500);}catch{$(id).focus();$(id).select();notice('Select and copy the highlighted text.');}}
async function init(){
  $('rulesBtn').onclick=()=>$('rules').showModal();$('closeRules').onclick=()=>$('rules').close();$('setupBtn').onclick=()=>$('setup').showModal();$('closeSetup').onclick=()=>$('setup').close();
  $('createMatch').onclick=createMatch;$('loadMatch').onclick=()=>{const id=$('matchId').value.trim();savedInvites(id);connect(id);};$('copyShare').onclick=e=>copy('shareLink',e.target);$('copyPrompt0').onclick=e=>copy('prompt0',e.target);$('copyPrompt1').onclick=e=>copy('prompt1',e.target);$('watchReplay').onclick=watchReplay;$('downloadReplay').onclick=downloadReplay;
  $('replaySeek').oninput=e=>{clearInterval(replayTimer);replayTimer=null;$('replayPlay').textContent='▶ Play';showFrame(Number(e.target.value));};$('replayNext').onclick=()=>showFrame(Math.min(replayIndex+1,replay.frames.length-1));$('replayPlay').onclick=()=>{if(replayTimer){clearInterval(replayTimer);replayTimer=null;$('replayPlay').textContent='▶ Play';return;}if(replayIndex>=replay.frames.length-1)showFrame(0);$('replayPlay').textContent='Ⅱ Pause';replayTimer=setInterval(()=>{if(!replay||replayIndex>=replay.frames.length-1){clearInterval(replayTimer);replayTimer=null;$('replayPlay').textContent='▶ Play';return;}showFrame(replayIndex+1);},850);};
  if(location.protocol==='file:'){notice('Run npm start in the agent-arena folder, then open http://127.0.0.1:4173. Live battles need the referee server.',true);$('createMatch').disabled=true;return;}
  try{const health=await api('/api/health');storageNotice.hidden=health.storage_mode!=='ephemeral';$('hostKeyWrap').hidden=!health.creation_requires_key;$('mcpUrl').value=location.origin+'/mcp';$('serverMode').textContent=health.public_origin?'REMOTE SERVER':'LOCAL SERVER';if(!health.public_origin)$('remoteNote').textContent='This server is local. Cloud-hosted assistants cannot reach localhost. Use a desktop MCP client with the stdio bridge, or deploy this backend to a public HTTPS host.';if(matchId()){savedInvites(matchId());await connect(matchId());}else notice('Create an arena, then connect two external assistants. No model API key needed.');}catch(e){notice('Cannot reach the referee: '+e.message,true);}
  setInterval(updateClock,1000);
}
init();

